"""Week-aware greedy scheduler (WFM-231), selected per client with `scheduler: week_aware`.

Same template-placement idea as `greedy.py`, but the rules of the newer contracts are enforced while
placing, against the agent's whole week, instead of being audited afterwards:

  * rest: `min_rest_hours` of elapsed time between one shift's end and the next shift's start (both ways)
  * split shifts only for the contracts in `split_shift_contracts`
  * hour caps (elapsed), at most `max_consecutive_days`, skills, one shift per local day
  * breaks: one per shift of `break.min_shift_hours` or more, started in the `break.window_hours` window
    after the shift starts, in the planning interval with the largest gross coverage surplus
    (agents on the queue ignoring breaks, minus required); ties go to the interval holding the fewest breaks

Coverage is planned against the required curve *net of breaks*: after the first placement pass the
breaks are placed by the rule above, intervals still short once breaks are taken out get another
shift, and the breaks are re-placed, until no interval is short or no shift can be added.

Deterministic: fixed template order, agent ids as the tie-break.
"""
from __future__ import annotations

from collections import defaultdict
from datetime import date, datetime, timedelta
from zoneinfo import ZoneInfo

import pandas as pd

from wfm.ingest.loader import local_days
from wfm.roster import Agent
from wfm.scheduler.greedy import Shift, _covered, _would_exceed_run
from wfm.scheduler.templates import Template, templates_for

MAX_REPAIR_ROUNDS = 400


class _Week:
    """Per-agent state for the week, so every rule can be checked against the whole schedule."""

    def __init__(self, cfg: dict, tz: str):
        self.caps = cfg["weekly_hours"]
        self.max_run = cfg["max_consecutive_days"]
        self.rest = timedelta(hours=float(cfg.get("min_rest_hours", 0)))
        self.split_ok = cfg.get("split_shift_contracts")      # None: every contract
        self.hours: dict[str, float] = defaultdict(float)
        self.days: dict[str, set[date]] = defaultdict(set)
        self.spans: dict[str, list[tuple[datetime, datetime]]] = defaultdict(list)

    def feasible(self, a: Agent, tpl: Template, day: date, segs, queue: str) -> bool:
        if queue not in a.skills or day in self.days[a.agent_id]:
            return False
        if tpl.is_split and self.split_ok is not None and a.contract not in self.split_ok:
            return False
        hrs = sum((e - s).total_seconds() for s, e in segs) / 3600.0
        if self.hours[a.agent_id] + hrs > self.caps[a.contract] + 1e-9:
            return False
        worked = self.days[a.agent_id] | {day}
        run, d = 1, day - timedelta(days=1)
        while d in worked:
            run, d = run + 1, d - timedelta(days=1)
        d = day + timedelta(days=1)
        while d in worked:
            run, d = run + 1, d + timedelta(days=1)
        if run > self.max_run:
            return False
        start, end = segs[0][0], segs[-1][1]
        for s0, e0 in self.spans[a.agent_id]:
            if e0 <= start:
                if start - e0 < self.rest:
                    return False
            elif s0 >= end:
                if s0 - end < self.rest:
                    return False
            else:
                return False
        return True

    def add(self, a: Agent, day: date, segs) -> None:
        self.hours[a.agent_id] += sum((e - s).total_seconds() for s, e in segs) / 3600.0
        self.days[a.agent_id].add(day)
        self.spans[a.agent_id].append((segs[0][0], segs[-1][1]))


def _pick_agent(week: _Week, agents: list[Agent], tpl, day, segs, q) -> Agent | None:
    cands = [a for a in agents if week.feasible(a, tpl, day, segs, q)]
    if not cands:
        return None
    # fewest hours so far keeps the load even; single-skill agents are used before multi-skill ones
    return min(cands, key=lambda x: (week.hours[x.agent_id], len(x.skills), x.agent_id))


def _net_shortfall(shifts, required, grid, grain: timedelta, length: timedelta) -> dict:
    """{(queue, t): required - net coverage} for intervals that are short, with breaks taken out."""
    net = defaultdict(int)
    for sh in shifts:
        for t in sh.intervals:
            net[(sh.queue, t)] += 1
        if sh.break_start is not None:
            for t in grid:
                if sh.break_start < t + grain and t < sh.break_start + length:
                    net[(sh.queue, t)] -= 1
    short = {}
    for q, req in required.items():
        for t, r in req.items():
            if r > net[(q, t)]:
                short[(q, t)] = r - net[(q, t)]
    return short


def schedule_week(req: pd.DataFrame, cfg: dict, agents: list[Agent], week: str) -> list[Shift]:
    tz = cfg["tz"]
    grain = timedelta(minutes=cfg["interval_minutes"])
    grain_h = cfg["interval_minutes"] / 60.0
    length = timedelta(minutes=cfg["break"]["minutes"])
    templates = templates_for(cfg)
    queues = list(dict.fromkeys(req["queue"]))
    required = {q: dict(zip(g["interval_start_utc"], g["required"])) for q, g in req.groupby("queue")}
    grid = sorted(set(req["interval_start_utc"]))
    z = ZoneInfo(tz)
    state = _Week(cfg, tz)
    shifts: list[Shift] = []
    days = local_days(week, tz)

    def place(tpl, q, day, segs, ivs, a):
        shifts.append(Shift(a.agent_id, q, tpl, day, segs, ivs))
        state.add(a, day, segs)

    # pass 1: cover the gross requirement day by day
    cover = {q: defaultdict(int) for q in queues}
    for day in days:
        day_grid = [t for t in grid if t.astimezone(z).date() == day]
        dead: set[tuple[str, str]] = set()
        while True:
            best, best_val = None, 0.0
            for tpl in templates:
                segs = tpl.segments_utc(day, tz)
                ivs = _covered(segs, day_grid)
                for q in queues:
                    if (tpl.id, q) in dead:
                        continue
                    val = sum(max(0, min(1, required[q][t] - cover[q][t])) for t in ivs)
                    if val > best_val + 1e-9:
                        best, best_val = (tpl, q, segs, ivs), val
            if best is None or best_val * grain_h < 0.5:
                break
            tpl, q, segs, ivs = best
            a = _pick_agent(state, agents, tpl, day, segs, q)
            if a is None:
                dead.add((tpl.id, q))
                continue
            place(tpl, q, day, segs, ivs, a)
            for t in ivs:
                cover[q][t] += 1

    # pass 2: breaks by the contract rule, then add shifts where the net coverage is still short
    place_breaks(shifts, req, cfg)
    best_short, best_state = None, None
    for _ in range(MAX_REPAIR_ROUNDS):
        short = _net_shortfall(shifts, required, grid, grain, length)
        total = sum(short.values())
        if best_short is None or total < best_short:
            best_short, best_state = total, list(shifts)
        if not short:
            break
        pick = None
        for tpl_day in days:
            day_grid = [t for t in grid if t.astimezone(z).date() == tpl_day]
            for tpl in templates:
                segs = tpl.segments_utc(tpl_day, tz)
                ivs = _covered(segs, day_grid)
                for q in queues:
                    val = sum(1 for t in ivs if short.get((q, t)))
                    if val and (pick is None or val / tpl.hours > pick[0] + 1e-9):
                        if any(state.feasible(a, tpl, tpl_day, segs, q) for a in agents):
                            pick = (val / tpl.hours, tpl, q, tpl_day, segs, ivs)
        if pick is None:
            break
        _, tpl, q, d, segs, ivs = pick
        a = _pick_agent(state, agents, tpl, d, segs, q)
        place(tpl, q, d, segs, ivs, a)
        place_breaks(shifts, req, cfg)
    else:
        short = _net_shortfall(shifts, required, grid, grain, length)
        if sum(short.values()) < best_short:
            best_short, best_state = sum(short.values()), list(shifts)
    if best_state is not None and len(best_state) != len(shifts):
        shifts = best_state
        place_breaks(shifts, req, cfg)
    return shifts


def place_breaks(shifts: list[Shift], req: pd.DataFrame, cfg: dict) -> None:
    """Breaks per the contract: window after shift start, interval of largest gross surplus.

    Gross surplus ignores breaks, so it does not depend on the order the breaks are placed in; ties
    go to the interval holding the fewest breaks so far (then the earliest).
    """
    rule = cfg["break"]
    length = timedelta(minutes=rule["minutes"])
    lo, hi = (timedelta(hours=h) for h in rule["window_hours"])
    required = {q: dict(zip(g["interval_start_utc"], g["required"])) for q, g in req.groupby("queue")}
    gross: dict[str, dict] = defaultdict(lambda: defaultdict(int))
    for sh in shifts:
        for t in sh.intervals:
            gross[sh.queue][t] += 1
    used: dict[str, dict] = defaultdict(lambda: defaultdict(int))
    for sh in shifts:
        sh.break_start, sh.break_minutes = None, 0
    for sh in sorted(shifts, key=lambda s: (s.segments[0][0], s.agent_id)):
        if sh.hours < rule["min_shift_hours"]:
            continue
        start = sh.segments[0][0]
        fits = [t for t in sh.intervals
                if start + lo <= t <= start + hi and any(s <= t and t + length <= e for s, e in sh.segments)]
        if not fits:
            continue
        q = sh.queue
        sh.break_start = min(fits, key=lambda t: (-(gross[q][t] - required[q].get(t, 0)), used[q][t], t))
        sh.break_minutes = rule["minutes"]
        used[q][sh.break_start] += 1

